            src = f.read()
        comments = []
        try:
            toks = tokenize.tokenize(io.BytesIO(src).readline)
            for tok in toks:
                if tok.type == tokenize.COMMENT:
                    comments.append((tok.start[0], tok.string))
        except Exception:
            # fallback: line-based, skip putative strings crudely
            text = src.decode('utf-8', 'replace')
            for i, line in enumerate(text.splitlines(), 1):
                idx = line.find('#')
                if idx != -1:
                    comments.append((i, line[idx:]))
        for lineno, s in comments:
            if 'TODO' in s:
                results.append((rel, lineno))

results.sort(key=lambda x: (x[0], x[1]))
with open('todos.txt', 'w') as out:
    for rel, lineno in results:
        out.write(f'{rel}:{lineno}\n')
print(f'Wrote {len(results)} entries')
